import { TOPOLOGY_PAGE_PROFILES } from "../config/topologyPageProfiles";
import { createHexGrid, getGridBounds } from "./hex";
import { createHomeSceneData } from "./siteKnowledge";

export async function createHomepageOpeningSceneTopology() {
  const homeProfile = TOPOLOGY_PAGE_PROFILES.home;
  const homeRadius = homeProfile.scene.radius;
  const homeCells = createHexGrid({
    radius: homeRadius,
    columns: homeProfile.scene.columns,
    rows: homeProfile.scene.rows,
    originQ: homeProfile.scene.originQ,
    originR: homeProfile.scene.originR,
  });
  const homeBounds = getGridBounds(homeCells, homeRadius);
  const { items, nodes, edges, activeItem } = await createHomeSceneData();
  const homeJson = JSON.stringify({
    nodes,
    edges,
    items,
    activeItemId: activeItem?.id ?? "operational-topology",
  });

  return {
    homeProfile,
    homeRadius,
    homeCells,
    homeBounds,
    items,
    nodes,
    edges,
    activeItem,
    homeJson,
  };
}
